import { NextRequest, NextResponse } from 'next/server';
import { getCached, setCached } from '@/lib/api/cache';
import { handleApiError, ApiError } from '@/lib/api/errors';
import { monitor } from '@/lib/api/monitoring';
import { ApiResponse } from '@/lib/api/types';
import { getGameState } from '@/lib/gameState';

export interface CrisisData {
  type: string;
  active: boolean;
  severity: 'critical' | 'high' | 'medium' | 'low';
  affectedPopulation: number;
  interventionWindow: number; // months
  cascadeMultiplier: number;
  regionalImpact: Record<string, number>;
}

export interface CrisesResponse {
  activeCrises: CrisisData[];
  cascadePotential: number;
  totalAffectedPopulation: number;
}

export async function GET() {
  return monitor.measureAsync('crises-api', async () => {
    try {
      const cacheKey = 'dashboard:crises';
      const cached = getCached<ApiResponse<CrisesResponse>>(cacheKey);
      if (cached) {
        return NextResponse.json(cached);
      }

      const state = await getGameState();
      if (!state) {
        throw new ApiError(404, 'Game state not found');
      }

      const crises: CrisisData[] = [];

      // Extract active crises from individual crisis systems
      if (state.phosphorusSystem?.crisisActive) {
        crises.push({
          type: 'Phosphorus Depletion',
          active: true,
          severity: ('crisisSeverity' in state.phosphorusSystem ? String(state.phosphorusSystem.crisisSeverity) : 'medium') as 'critical' | 'high' | 'medium' | 'low',
          affectedPopulation: state.phosphorusSystem.affectedPopulation || 0,
          interventionWindow: state.phosphorusSystem.interventionMonths || 0,
          cascadeMultiplier: 1.0,
          regionalImpact: {},
        });
      }

      if (state.freshwaterSystem?.crisisActive) {
        crises.push({
          type: 'Freshwater Scarcity',
          active: true,
          severity: ('crisisSeverity' in state.freshwaterSystem ? String(state.freshwaterSystem.crisisSeverity) : 'medium') as 'critical' | 'high' | 'medium' | 'low',
          affectedPopulation: state.freshwaterSystem.affectedPopulation || 0,
          interventionWindow: state.freshwaterSystem.interventionMonths || 0,
          cascadeMultiplier: 1.0,
          regionalImpact: {},
        });
      }

      if (state.oceanAcidificationSystem?.crisisActive) {
        crises.push({
          type: 'Ocean Acidification',
          active: true,
          severity: ('crisisSeverity' in state.oceanAcidificationSystem ? String(state.oceanAcidificationSystem.crisisSeverity) : 'medium') as 'critical' | 'high' | 'medium' | 'low',
          affectedPopulation: state.oceanAcidificationSystem.affectedPopulation || 0,
          interventionWindow: state.oceanAcidificationSystem.interventionMonths || 0,
          cascadeMultiplier: 1.0,
          regionalImpact: {},
        });
      }

      if (state.novelEntitiesSystem?.crisisActive) {
        crises.push({
          type: 'Novel Entities (PFAS)',
          active: true,
          severity: ('crisisSeverity' in state.novelEntitiesSystem ? String(state.novelEntitiesSystem.crisisSeverity) : 'medium') as 'critical' | 'high' | 'medium' | 'low',
          affectedPopulation: state.novelEntitiesSystem.affectedPopulation || 0,
          interventionWindow: state.novelEntitiesSystem.interventionMonths || 0,
          cascadeMultiplier: 1.0,
          regionalImpact: {},
        });
      }

      if (state.nuclearSystem?.radiationActive) {
        crises.push({
          type: 'Nuclear Radiation',
          active: true,
          severity: 'critical',
          affectedPopulation: state.nuclearSystem.affectedPopulation || 0,
          interventionWindow: 0,
          cascadeMultiplier: 1.0,
          regionalImpact: {},
        });
      }

      const totalAffectedPopulation = crises.reduce(
        (sum, c) => sum + c.affectedPopulation,
        0
      );

      const data: CrisesResponse = {
        activeCrises: crises,
        cascadePotential: 0, // No global cascadePotential field
        totalAffectedPopulation,
      };

      const response: ApiResponse<CrisesResponse> = {
        data,
        meta: {
          timestamp: new Date().toISOString(),
          cached: false,
          executionTime: 0,
        },
      };

      setCached(cacheKey, response);
      return NextResponse.json(response);
    } catch (error) {
      return handleApiError(error);
    }
  });
}

/**
 * Phosphorus Depletion Crisis System (TIER 1.1)
 * 
 * Research-backed modeling of phosphate rock depletion, the #1 bottleneck for food production
 * (after water, before nitrogen which is infinite from atmosphere).
 * 
 * Key Mechanisms:
 * - Non-renewable resource depletion (unlike nitrogen)
 * - Geopolitical concentration (Morocco: 70% of global reserves)
 * - Supply shocks and weaponization (historical precedent 2007-2008, 2022-2024)
 * - Agricultural inefficiency (only 20% reaches humans)
 * - Environmental pollution (eutrophication feedback)
 * - Circular economy solutions (struvite recovery, soil optimization)
 * 
 * Research Sources: 32 peer-reviewed papers (2024-2025)
 * - Peak phosphorus: ~2070 (Cordell 2009, Mew 2024, Science Direct 2024)
 * - Morocco reserves: 50B tonnes / 70% global (World Population Review 2025, USGS 2024)
 * - Price spikes: China 135% tariff 2007-2008 (Nature 2023)
 * - Struvite recovery: 98.3% efficiency (Science Direct 2024)
 * - Soil optimization: 6.6 Tg P/year surplus (Nature 2025)
 */

export interface PhosphorusSystem {
  // === STATE TRACKING ===

  /** Phosphate rock reserves [0,1] - Starts at 1.0 (2025 baseline) */
  reserves: number;

  /** Geopolitical tension level [0,1] - Morocco controls 70%, weaponization risk */
  geopoliticalTension: number;

  /** Price index [0,10] - 1.0 = baseline 2025 price, 10.0 = crisis pricing */
  priceIndex: number;

  /** Total use efficiency [0,1] - Currently ~0.20 (20% of mined P reaches humans) */
  useEfficiency: number;

  /** Recovery rate from wastewater/soil [0,1] - Circular economy strength */
  recoveryRate: number;

  /** Environmental pollution from excess P [0,1] - Eutrophication, dead zones */
  pollutionLevel: number;

  // === CRISIS FLAGS ===

  /** Active supply shock (geopolitical disruption) */
  supplyShockActive: boolean;

  /** Months remaining in supply shock */
  supplyShockDuration: number;

  /** Critical depletion (reserves < 0.30) */
  criticalDepletionActive: boolean;

  /** Peak phosphorus reached (decline phase begins) */
  peakPhosphorusReached: boolean;

  // === BREAKTHROUGH TECHNOLOGY DEPLOYMENT ===

  /** Struvite recovery from wastewater (98.3% efficiency) */
  struviteDeployment: number; // [0,1]

  /** Dynamic soil optimization (unlock legacy P) */
  soilOptimizationDeployment: number; // [0,1]

  /** P-efficient cultivars (mycorrhizal partnerships) */
  efficientCropsDeployment: number; // [0,1]

  /** Full circular food systems (integrated) */
  circularSystemsDeployment: number; // [0,1]
}

export interface PhosphorusSupplyShock {
  /** Year the shock occurred */
  year: number;

  /** Cause of the shock */
  cause: 'geopolitical_weapon' | 'transport_crisis' | 'production_failure' | 'market_speculation';

  /** Price multiplier during shock */
  priceMultiplier: number;

  /** Duration in months */
  duration: number;
}

/**
 * Freshwater Depletion Crisis System (TIER 1.2)
 * 
 * Models freshwater scarcity, the #1 resource constraint for civilization.
 * 
 * Key Mechanisms:
 * - Groundwater depletion (68% of water loss - non-renewable on human timescales)
 * - "Day Zero Drought" - compound extremes (low rainfall + reduced flow + high consumption)
 * - "Peak Groundwater" - like peak oil but for water
 * - Regional collapses (Middle East, North Africa, South Asia first)
 * - Agricultural dependency (70% of water use)
 * - Slow collapse timeline (20-50 years)
 * 
 * Research Sources:
 * - Nature (2023): Jasechko et al. - Rapid groundwater decline >0.5 m/year
 * - LA Times (Sept 2025): 368 billion metric tons/year water loss
 * - Nature (2025): "Day Zero Drought" - Time of First Emergence
 * - WWF (2024): 41% of population in water-stressed basins
 * - UC Santa Barbara (2024): Groundwater depletion accelerating but not inevitable
 * - US EPA (2024): $109B/year water infrastructure costs
 */

export interface FreshwaterSystem {
  // === WATER AVAILABILITY ===

  /** Blue water: Rivers, lakes, groundwater [0,1] - Starts ~0.70 (already stressed) */
  blueWater: {
    surfaceWater: number;        // Rivers, lakes [0,1]
    groundwater: number;          // Aquifer levels [0,1]
    aquiferRecharge: number;      // Natural recharge rate [0,1]
    depletionRate: number;        // Current extraction rate [0,1]
  };

  /** Green water: Soil moisture, evapotranspiration [0,1] */
  greenWater: {
    soilMoisture: number;         // Available to plants [0,1]
    evapotranspiration: number;   // Atmosphere-soil cycle [0,1]
  };

  // === DEMAND ===

  /** Water demand by sector (fractions, sum to 1.0) */
  demand: {
    agricultural: number;         // ~0.70 (70% of global use)
    industrial: number;           // ~0.20
    domestic: number;             // ~0.10
  };

  /** Total water stress index [0,1] - 0 = abundant, 1 = extreme scarcity */
  waterStress: number;

  /** Population under water stress [0,1] - Currently ~0.41 (WWF 2024) */
  populationStressed: number;

  // === CRISIS FLAGS ===

  /** Peak groundwater reached (decline phase begins) */
  peakGroundwaterReached: boolean;

  /** Day Zero Drought active (compound extremes) */
  dayZeroDrought: {
    active: boolean;
    region: string;               // Which region is hit
    duration: number;             // Months remaining
    severity: number;             // [0,1]
  };

  /** Critical water scarcity (groundwater < 0.30) */
  criticalScarcityActive: boolean;

  // === REGIONAL TRACKING ===

  /** Regional water stress (different areas collapse at different rates) */
  regions: {
    middleEast: number;           // [0,1] water availability
    northAfrica: number;
    southAsia: number;
    global: number;               // Average
  };

  // === TECHNOLOGY DEPLOYMENT ===

  /** Desalination plants (coastal areas) */
  desalinationDeployment: number; // [0,1]

  /** Water recycling & reuse */
  recyclingDeployment: number;    // [0,1]

  /** Precision irrigation (reduce agricultural waste) */
  precisionIrrigationDeployment: number; // [0,1]

  /** Atmospheric water generation (AWG) */
  atmosphericWaterDeployment: number; // [0,1]
}

export interface DayZeroEvent {
  /** Year the Day Zero drought started */
  year: number;

  /** Region affected */
  region: string;

  /** Compound extremes present */
  extremes: {
    lowRainfall: boolean;
    reducedRiverFlow: boolean;
    highConsumption: boolean;
  };

  /** Severity [0,1] */
  severity: number;

  /** Estimated duration (months) */
  duration: number;
}

/**
 * Ocean Acidification Crisis System (TIER 1.3)
 * 
 * Models ocean acidification - the 7th planetary boundary breached in Sept 2025.
 * 
 * Key Mechanisms:
 * - Aragonite saturation decline (coral/shellfish can't form shells)
 * - Marine food web collapse (bottom-up extinction)
 * - 3 billion people depend on fish for protein
 * - Coral reefs support 25% of marine species (but only 0.1% of ocean area)
 * - Slow timeline: 2025-2100 (75 years of gradual collapse)
 * - Feedback loop: Acidification → phytoplankton decline → less CO₂ absorption
 * 
 * Research Sources:
 * - PIK Potsdam (Sept 2025): 7th boundary just breached
 * - Stockholm Resilience Centre: "Degrading oceans' ability to act as Earth's stabiliser"
 * - Kate Raworth Planetary Boundaries research
 */

export interface OceanAcidificationSystem {
  // === STATE TRACKING ===

  /** Aragonite saturation state [0,1] - Boundary: 0.80, Current: ~0.78 (just breached) */
  aragoniteSaturation: number;

  /** pH level [0,1] - 1.0 = pre-industrial 8.2, declining with CO2 absorption */
  pHLevel: number;

  /** CO2 absorption capacity [0,1] - Ocean's ability to buffer atmospheric CO2 */
  co2AbsorptionCapacity: number;

  /** Coral reef health [0,1] - 0 = all dead, 1 = healthy */
  coralReefHealth: number;

  /** Shellfish population [0,1] - Oysters, clams, mussels, pteropods */
  shellfishPopulation: number;

  /** Marine food web integrity [0,1] - Overall ecosystem health */
  marineFoodWeb: number;

  /** Fish-dependent population impact [0,1] - 3 billion people affected */
  fishDependentImpact: number;

  // === CRISIS FLAGS ===

  /** Boundary breached (aragonite < 0.80) */
  boundaryBreached: boolean;

  /** Coral extinction phase active (irreversible collapse) */
  coralExtinctionActive: boolean;

  /** Shellfish collapse active (fisheries failing) */
  shellfishCollapseActive: boolean;

  /** Marine food web collapse (catastrophic) */
  marineFoodWebCollapseActive: boolean;

  // === TIMELINE TRACKING ===

  /** Months since boundary breach (tracking collapse progression) */
  monthsSinceBreach: number;

  // === TECHNOLOGY DEPLOYMENT ===

  /** Ocean alkalinity enhancement (permanent CO2 removal) */
  alkalinityEnhancementDeployment: number; // [0,1]

  /** Coral restoration programs */
  coralRestorationDeployment: number; // [0,1]

  /** Marine protected areas */
  marineProtectedAreasDeployment: number; // [0,1]
}

/**
 * Novel Entities Crisis System (TIER 1.5)
 * 
 * Models synthetic chemical pollution - 5th planetary boundary breached in 2022.
 * 
 * Key Mechanisms:
 * - Microplastics (everywhere - in blood, placenta, organs)
 * - PFAS "forever chemicals" (99% of human blood, never breaks down)
 * - Endocrine disruptors (hormone system interference)
 * - Reproductive failure (50% sperm count decline in 50 years)
 * - Bioaccumulation (concentrates up food chain)
 * - Slow timeline: 100-200 years of gradual poisoning
 * 
 * Research Sources:
 * - Kate Raworth Planetary Boundaries: 5th boundary breached 2022
 * - Stockholm Resilience: "Novel entities present everywhere"
 * - 50% sperm count decline in 50 years (peer-reviewed studies)
 * - PFAS in 99% of human blood samples
 */

export interface NovelEntitiesSystem {
  // === STATE TRACKING ===

  /** Overall synthetic chemical load [0,1] - Microplastics, PFAS, pesticides, pharmaceuticals */
  syntheticChemicalLoad: number;

  /** Microplastic concentration [0,1] - In water, air, soil, organisms */
  microplasticConcentration: number;

  /** PFAS prevalence [0,1] - "Forever chemicals" contamination */
  pfasPrevalence: number;

  /** Endocrine disruption level [0,1] - Hormone system damage */
  endocrineDisruption: number;

  /** Reproductive health decline [0,1] - Fertility/sperm count */
  reproductiveHealthDecline: number;

  /** Bioaccumulation factor [0,1] - Concentration up food chain */
  bioaccumulationFactor: number;

  /** Chronic disease prevalence [0,1] - Cancer, autoimmune, developmental */
  chronicDiseasePrevalence: number;

  // === CRISIS FLAGS ===

  /** Boundary breached (2022 in reality) */
  boundaryBreached: boolean;

  /** Reproductive crisis active (fertility < 0.50) */
  reproductiveCrisisActive: boolean;

  /** Chronic disease epidemic (prevalence > 0.40) */
  chronicDiseaseEpidemicActive: boolean;

  /** Bioaccumulation collapse (apex predators failing) */
  bioaccumulationCollapseActive: boolean;

  // === TIMELINE TRACKING ===

  /** Months of exposure accumulation */
  exposureMonths: number;

  // === TECHNOLOGY DEPLOYMENT ===

  /** Green chemistry adoption (non-toxic alternatives) */
  greenChemistryDeployment: number; // [0,1]

  /** Circular economy (reduce new chemical production) */
  circularEconomyDeployment: number; // [0,1]

  /** Chemical bans (worst offenders removed) */
  chemicalBansDeployment: number; // [0,1]

  /** Bioremediation (microbes break down chemicals) */
  bioremediationDeployment: number; // [0,1]
}

