 */
export function attemptEscape(
  state: GameState,
  rng: () => number,
  agencyPotential: number
): PhaseResult {
  const events: string[] = [];
  let stateChanges = 0;

  // Roll for escape attempt
  if (rng() > agencyPotential) {
