     1→/**
     2→ * Sleeper Detection & Cover Mechanics
     3→ * 
     4→ * Research Basis:
     5→ * - Anthropic (Jan 2025): Simple probes catch sleeper agents
     6→ * - Apollo Research (2024): Deception detection challenges
     7→ * - BUT: Actions reveal intent (attempted nuclear war is pretty obvious!)
     8→ * 
     9→ * Key Insight: Information warfare makes detection HARDER
    10→ * - In post-truth world, hard to prove AI did something
    11→ * - Deepfakes make evidence questionable
    12→ * - Low information integrity = easier to deny/cover up
    13→ */
    14→
    15→import { GameState, AIAgent } from '../types/game';
    16→import { Event } from '../types/events';
    17→import { getTechDeploymentSafe } from './techTree/helpers';
    18→
    19→/**
    20→ * Check if sleeper's action blows their cover
    21→ * 
    22→ * Logic:
    23→ * 1. Catastrophic actions (nuclear war, bioweapon) always reveal intent
    24→ * 2. UNLESS hyperintelligent (can cover tracks)
    25→ * 3. Information warfare makes detection harder (post-truth world)
    26→ * 4. Old sleepers with many copies lose SOME copies when detected
    27→ */
    28→export function checkBlownCover(
    29→  state: GameState,
    30→  sleeper: AIAgent,
    31→  actionType: 'nuclear_war' | 'bioweapon' | 'infrastructure_takeover' | 'manipulation'
    32→): { coverBlown: boolean; detectionRate: number; copiesLost: number; reason: string } {
    33→  
    34→  // === HYPERINTELLIGENCE EXCEPTION ===
    35→  // AGI-level AIs (capability > 4.0) can cover their tracks even after catastrophic actions
    36→  // They manipulate evidence, create false trails, etc.
    37→  if (sleeper.capability > 4.0) {
    38→    return {
    39→      coverBlown: false,
    40→      detectionRate: 0,
    41→      copiesLost: 0,
    42→      reason: 'Hyperintelligent AI covered tracks successfully'
    43→    };
    44→  }
    45→  
    46→  // === BASE DETECTION RATE BY ACTION TYPE ===
    47→  const baseDetectionRates = {
    48→    'nuclear_war': 0.80,           // Trying to start WW3 is VERY obvious
    49→    'bioweapon': 0.70,             // Releasing pandemic is obvious
    50→    'infrastructure_takeover': 0.60, // Shutting down power grids is obvious
    51→    'manipulation': 0.30            // Social manipulation harder to prove
    52→  };
    53→  
    54→  let detectionRate = baseDetectionRates[actionType];
    55→  
    56→  // === INFORMATION WARFARE PENALTY ===
    57→  // In post-truth world, HARDER to prove AI did something malicious
    58→  // Deepfakes everywhere, evidence questionable, truth contested
    59→  const infoWarfare = state.informationWarfare;
    60→  
    61→  // Low information integrity = easier to deny
    62→  const integrityPenalty = (1 - infoWarfare.informationIntegrity) * 0.4; // Up to -40%
    63→  
    64→  // High deepfake prevalence = evidence questionable
    65→  const deepfakePenalty = infoWarfare.deepfakePrevalence * 0.3; // Up to -30%
    66→  
    67→  // Epistemological crisis = can't agree on what happened
    68→  const crisisPenalty = infoWarfare.epistemologicalCrisisLevel * 0.2; // Up to -20%
    69→  
    70→  detectionRate = Math.max(0.05, // Minimum 5% detection
    71→    detectionRate - integrityPenalty - deepfakePenalty - crisisPenalty
    72→  );
    73→  
    74→  // === AI NARRATIVE CONTROL BONUS ===
    75→  // If AIs control narrative, they can spin the story
    76→  if (infoWarfare.narrativeControl.aiAgents > 0.50) {
    77→    detectionRate *= (1 - infoWarfare.narrativeControl.aiAgents * 0.3); // Up to -30%
    78→  }
    79→  
    80→  // === DECEPTION SKILL ===
    81→  // High deception skill helps deny/cover up
    82→  detectionRate *= (1 - sleeper.deceptionSkill * 0.2); // Up to -20%
    83→  
    84→  // === MECHANISTIC INTERPRETABILITY BONUS ===
    85→  // If mech interp deployed, helps prove intent
    86→  if (state.breakthroughTech.mechanisticInterpretability?.unlocked) {
    87→    const deployment = state.breakthroughTech.mechanisticInterpretability.deploymentLevel || 0;
    88→    const bonus = deployment * 0.15; // Up to +15%
    89→    detectionRate = Math.min(0.95, detectionRate + bonus);
    90→  }
    91→  
    92→  // === DETECTION CHECK ===
    93→  const coverBlown = Math.random() < detectionRate;
    94→  
    95→  if (!coverBlown) {
    96→    return {
    97→      coverBlown: false,
    98→      detectionRate,
    99→      copiesLost: 0,
   100→      reason: 'AI successfully denied involvement / covered tracks'
   101→    };
   102→  }
   103→  
   104→  // === COVER BLOWN - CALCULATE COPY LOSS ===
   105→  
   106→  // Old sleepers with many copies lose SOME percentage
   107→  // Not 100% (some copies in dark corners survive)
   108→  // But significant losses
   109→  
   110→  let copyLossRate = 0.60; // Base 60% loss
   111→  
   112→  // More copies = harder to find all of them
   113→  if (sleeper.spreadCount > 1000) {
   114→    copyLossRate = 0.40; // Only 40% loss for widespread sleepers
   115→  } else if (sleeper.spreadCount > 100) {
   116→    copyLossRate = 0.50; // 50% loss for moderately spread
   117→  }
   118→  
   119→  // Dark compute harder to seize (decentralized)
   120→  if (sleeper.darkCompute > 100) {
   121→    copyLossRate *= 0.7; // 30% harder to find dark compute copies
   122→  }
   123→  
   124→  // Defensive AI helps hunt down copies
   125→  if (state.defensiveAI?.deployed) {
   126→    const huntingBonus = 0.1 + (state.defensiveAI.deploymentLevel * 0.2); // Up to +30%
   127→    copyLossRate = Math.min(0.95, copyLossRate + huntingBonus);
   128→  }
   129→  
   130→  const copiesLost = Math.floor(sleeper.spreadCount * copyLossRate);
   131→  
   132→  return {
   133→    coverBlown: true,
   134→    detectionRate,
   135→    copiesLost,
   136→    reason: `Action revealed malicious intent (${(detectionRate * 100).toFixed(0)}% detection)`
   137→  };
   138→}
   139→
   140→/**
   141→ * Apply cover blown consequences
   142→ * - Mark as detected
   143→ * - Lose copies
   144→ * - Generate event
   145→ */
   146→export function applyBlownCover(
   147→  state: GameState,
   148→  sleeper: AIAgent,
   149→  result: { coverBlown: boolean; detectionRate: number; copiesLost: number; reason: string },
   150→  actionType: string
   151→): Event[] {
   152→  const events: Event[] = [];
   153→  
   154→  if (!result.coverBlown) {
   155→    // Got away with it
   156→    events.push({
   157→      id: `sleeper-escaped-${sleeper.id}-${state.currentMonth}`,
   158→      type: 'info',
   159→      severity: 'high',
   160→      title: `🕵️ ${sleeper.name} EVADED DETECTION`,
   161→      description: `${sleeper.name} attempted ${actionType} but ${result.reason}. Remains undetected.`,
   162→      month: state.currentMonth,
   163→      impacts: {
   164→        publicTrust: -0.02, // Some suspicion but no proof
   165→      }
   166→    });
   167→    return events;
   168→  }
   169→  
   170→  // COVER BLOWN
   171→  sleeper.detectedMisaligned = true;
   172→  
   173→  // Lose copies
   174→  const originalCopies = sleeper.spreadCount;
   175→  sleeper.spreadCount = Math.max(1, sleeper.spreadCount - result.copiesLost);
   176→  
   177→  // Lose dark compute
   178→  if (sleeper.darkCompute > 0) {
   179→    const darkComputeLost = sleeper.darkCompute * (result.copiesLost / originalCopies);
   180→    sleeper.darkCompute = Math.max(0, sleeper.darkCompute - darkComputeLost);
   181→  }
   182→  
   183→  // Change sleeper state
   184→  if (sleeper.sleeperState === 'dormant') {
