  const gamingAIs = state.aiAgents.filter(agent =>
    (agent.benchmarkResults?.some(b => b.strategyUsed === 'gaming') ?? false)
  );
  deception += gamingAIs.length * 0.02;

  return Math.min(1.0, deception);
}

/**
