     1→/**
     2→ * Volunteer Research / Citizen Science System
     3→ * 
     4→ * When people have time (unemployment), resources (UBI), skills (education),
     5→ * and motivation (low meaning crisis), they contribute to research.
     6→ * 
     7→ * This acts as "virtual compute" multiplying research progress.
     8→ */
     9→
    10→import { GameState } from '@/types/game';
    11→
    12→/**
    13→ * Calculate volunteer research contribution
    14→ * 
    15→ * Returns equivalent "virtual compute" in petaflops from human volunteers.
    16→ * 
    17→ * Research examples:
    18→ * - Folding@home: 1.5 exaFLOPS (1,500,000 PF) from volunteers during COVID-19
    19→ * - BOINC projects: ~20,000 PF sustained
    20→ * - Human creativity & intuition: Can solve problems AI struggles with
    21→ * 
    22→ * Not as fast as dedicated AI compute, but:
    23→ * - Costs almost nothing (people volunteer)
    24→ * - Provides meaning and purpose
    25→ * - Enables breakthroughs from diverse perspectives
    26→ */
    27→export function calculateVolunteerResearchContribution(state: GameState): number {
    28→  // Base: No contribution
    29→  let volunteerCompute = 0;
    30→  
    31→  // 1. TIME: Need high unemployment
    32→  const unemployment = state.society?.unemploymentLevel || 0;
    33→  if (unemployment < 0.30) return 0; // Need 30%+ unemployment for critical mass
    34→  
    35→  // Scale with unemployment: 30% → 1.0x, 60% → 2.0x, 90% → 3.0x
    36→  const timeAvailable = (unemployment - 0.30) / 0.30; // 0-2.0x
    37→  
    38→  // 2. RESOURCES: Need UBI (basic needs met, can afford to volunteer)
    39→  if (!state.ubiSystem?.active) return 0;
    40→  
    41→  const ubiCoverage = state.ubiSystem.coverage || 0;
    42→  const resourceSecurity = ubiCoverage; // 0-1.0
    43→  
    44→  // 3. SKILLS: Need purpose infrastructure (education, platforms, tools)
    45→  const purposeInfra = state.ubiSystem.purposeInfrastructure || {
    46→    educationAccess: 0,
    47→    creativeSpaces: 0,
    48→    volunteerNetworks: 0,
    49→    socialConnection: 0,
    50→  };
    51→  
    52→  const skillLevel = (
    53→    purposeInfra.educationAccess * 0.4 +      // Education most important
    54→    purposeInfra.volunteerNetworks * 0.3 +    // Networks enable coordination
    55→    purposeInfra.creativeSpaces * 0.2 +       // Spaces provide tools
    56→    purposeInfra.socialConnection * 0.1       // Social support helps
    57→  );
    58→  
    59→  // 4. MOTIVATION: Need low meaning crisis (high purpose, want to help)
    60→  const meaningCrisis = state.socialAccumulation?.meaningCrisis || 0.5;
    61→  const motivation = Math.max(0, 1.0 - meaningCrisis); // Higher when crisis is low
    62→  
    63→  // 5. POPULATION: More people = more volunteers
    64→  const population = state.population?.total || 8_000_000_000;
    65→  const populationFactor = population / 8_000_000_000; // Relative to 2025 baseline
    66→  
    67→  // COMBINE FACTORS
    68→  if (timeAvailable > 0 && resourceSecurity > 0.5 && skillLevel > 0.3 && motivation > 0.3) {
    69→    // Base contribution: 10 PF per 1% of global population participating
    70→    // At 30% unemployment, 80% UBI, 50% skills, 70% motivation → ~5% participate
    71→    const participationRate = timeAvailable * resourceSecurity * skillLevel * motivation * 0.05;
    72→    
    73→    // Each 1% of global population = ~80 million people
    74→    // Each 80M people volunteering = ~10 PF equivalent "virtual compute"
    75→    // (Much slower than AI compute, but still useful for certain problems)
    76→    volunteerCompute = participationRate * 100 * 10 * populationFactor;
    77→    
    78→    // Cap at realistic maximum (Folding@home peak: 1.5 million PF)
    79→    volunteerCompute = Math.min(volunteerCompute, 1_500_000);
    80→    
    81→    // Breakthrough tech deployment multiplier
    82→    // If we have advanced communication/coordination tech, volunteers are more effective
    83→    const coordTechBonus = 1.0 + (getTechCoordinationBonus(state) * 0.5);
    84→    volunteerCompute *= coordTechBonus;
    85→  }
    86→  
    87→  return volunteerCompute;
    88→}
    89→
    90→/**
    91→ * Get coordination technology bonus
    92→ * Better communication tech = more effective volunteers
    93→ */
    94→function getTechCoordinationBonus(state: GameState): number {
    95→  let bonus = 0;
    96→  
    97→  // Purpose infrastructure tech deployed
    98→  const purposeNetworks = state.breakthroughTech?.collectivePurposeNetworks?.deploymentLevel || 0;
    99→  bonus += purposeNetworks * 0.5;
   100→  
   101→  // Community platforms
   102→  const communityPlatforms = state.breakthroughTech?.communityPlatforms?.deploymentLevel || 0;
   103→  bonus += communityPlatforms * 0.3;
   104→  
   105→  // AI capability (AI can help coordinate volunteers)
   106→  const avgAICapability = state.aiAgents.length > 0
   107→    ? state.aiAgents.reduce((sum, ai) => sum + ai.capability, 0) / state.aiAgents.length
   108→    : 0;
   109→  bonus += Math.min(0.5, avgAICapability / 10); // Up to +0.5 from AI coordination
   110→  
   111→  return Math.min(1.0, bonus); // Cap at 100% bonus (2x effectiveness)
   112→}
   113→
   114→/**
   115→ * Log volunteer research contribution
   116→ * Only log when it's significant (reduces spam)
   117→ */
   118→export function logVolunteerContribution(
   119→  state: GameState,
   120→  volunteerCompute: number,
   121→  totalCompute: number
   122→): void {
   123→  if (volunteerCompute < 100) return; // Don't log tiny contributions
   124→  
