   132→  console.log(`   Virtual Compute: ${volunteerCompute.toFixed(0)} PF (${percentage.toFixed(1)}% of total)`);
   133→  console.log(`   Volunteers provide distributed problem-solving, creativity, intuition`);
   134→}
   135→
   136→/**
   137→ * Calculate what % of population is volunteering
   138→ */
   139→function calculateParticipationRate(state: GameState): number {
   140→  const unemployment = state.society?.unemploymentLevel || 0;
   141→  if (unemployment < 0.30) return 0;
   142→  
   143→  const ubiCoverage = state.ubiSystem?.coverage || 0;
