  pressure += (resourceDepletion / 100) * 0.2; // Max 0.2 pressure

  // Nuclear conflict (existential threat → emergency powers)
  const anyNuclearWar = state.nuclearStates?.some(ns => ns.atWar) ?? false;
  if (anyNuclearWar) {
