    switch (shock.type) {
      case 'climate':
        climateMortality *= shock.magnitude;
        break;
      case 'famine':
        famineMortality *= shock.magnitude;
        break;
      case 'disease':
        diseaseMortality *= shock.magnitude;
        break;
      case 'ecosystem':
        ecosystemMortality *= shock.magnitude;
        break;
    }
  }

