  militaryData.set('Bangladesh', {
    militaryCapability: 0.05,  // Internal security only
    militarySpendingPercent: 1.2,
    militarySpendingAbsolute: 4.6,
    militaryCO2Emissions: 0.5,
    militaryBases: new Map(),
