    console.log(`   War deaths reduced: ${(originalWarDeaths * 1000).toFixed(1)}M → ${(pop.deathsByCategory.war * 1000).toFixed(1)}M`);
    console.log(`   Lives saved: ${(deathsAverted * 1000).toFixed(1)}M`);

    return true;
  }

